              "dir": "ltr",
              "code": "static void Main()\n{\n    Console.WriteLine(\"please enter 0 or 1\");\n    int i = int.Parse(Console.ReadLine());\n    if (i == 0)\n    {\n        Console.WriteLine(\"000\");\n        Console.WriteLine(\"0 0\");\n        Console.WriteLine(\"000\");\n    }\n    if (i == 1)\n    {\n        Console.WriteLine(\"1\");\n        Console.WriteLine(\"1\");\n        Console.WriteLine(\"1\");\n    }\n}"
